1	import { db } from "../lib/db";
2	import { SANDBOX } from "../lib/sandbox";
3	import type { SftpServer } from "../lib/sftp";
4	import { decryptSecret } from "../lib/crypto-box";
5	import {
6	  withServerSsh,
7	  exec,
8	  execInput,
9	  assertIdent,
10	  assert,
11	  shellQuote,
12	  pkgInstallPrefix,
13	  SETUP_TIMEOUT_MS,
14	  INSTALL_TIMEOUT_MS,
15	  QUICK_TIMEOUT_MS,
16	} from "../lib/ssh-exec";
17	import type { Job } from "@prisma/client";
18	import type { Client } from "ssh2";
19	
20	/**
21	 * Control-panel DB_CREATE / DB_DELETE handlers (MySQL/MariaDB & PostgreSQL).
22	 *
23	 * Registered in worker/index.ts:
24	 *   DB_CREATE: dbCreate,
25	 *   DB_DELETE: dbDelete,
26	 *
27	 * The generated DB password is decrypted IN MEMORY from `passwordEnc`, applied
28	 * via the DB client's STDIN (never an argv token — mirrors migrate-real.ts), and
29	 * then `passwordEnc` is CLEARED. Engine is installed on first use.
30	 *
31	 * SANDBOX / non-ENABLE_REAL_CPANEL: no SSH — status flips to ACTIVE and the
32	 * secret is scrubbed, exactly like the rest of the platform.
33	 */
34	
35	const REAL = !SANDBOX && process.env.ENABLE_REAL_CPANEL === "1";
36	
37	async function notify(userId: string, title: string, body?: string, href?: string) {
38	  try {
39	    await db.notification.create({ data: { userId, title, body, href } });
40	  } catch (e) {
41	    console.error("[cpanel/db] notify failed", e);
42	  }
43	}
44	
45	async function loadDb(job: Job) {
46	  const p = (job.payload ?? {}) as { databaseId?: string };
47	  if (!p.databaseId) throw new Error("db job: missing databaseId");
48	  const row = await db.vpsDatabase.findUnique({ where: { id: p.databaseId } });
49	  if (!row) throw new Error(`VpsDatabase ${p.databaseId} not found`);
50	  return row;
51	}
52	
53	async function sshServer(serverId: string): Promise<SftpServer> {
54	  const s = await db.server.findUnique({
55	    where: { id: serverId },
56	    select: {
57	      id: true,
58	      rootPassword: true,
59	      rootPasswordEnc: true,
60	      sshPort: true,
61	      dedicatedIp: { select: { address: true } },
62	    },
63	  });
64	  if (!s) throw new Error(`Server ${serverId} not found`);
65	  return s as SftpServer;
66	}
67	
68	export async function ensureMysql(conn: Client): Promise<void> {
69	  const have = await exec(conn, "command -v mysql >/dev/null 2>&1 && echo yes || echo no", QUICK_TIMEOUT_MS);
70	  if (have.stdout.trim() === "yes") return;
71	  const prefix = await pkgInstallPrefix(conn);
72	  const inst = await exec(conn, `${prefix} mariadb-server || ${prefix} default-mysql-server`, INSTALL_TIMEOUT_MS);
73	  if (inst.code !== 0) throw new Error(`MySQL/MariaDB install failed: ${(inst.stderr || inst.stdout).trim().slice(0, 200)}`);
74	  await exec(conn, "systemctl enable --now mariadb 2>/dev/null || systemctl enable --now mysql", SETUP_TIMEOUT_MS);
75	}
76	
77	export async function ensurePostgres(conn: Client): Promise<void> {
78	  const have = await exec(conn, "command -v psql >/dev/null 2>&1 && echo yes || echo no", QUICK_TIMEOUT_MS);
79	  if (have.stdout.trim() === "yes") return;
80	  const prefix = await pkgInstallPrefix(conn);
81	  const inst = await exec(conn, `${prefix} postgresql`, INSTALL_TIMEOUT_MS);
82	  if (inst.code !== 0) throw new Error(`PostgreSQL install failed: ${(inst.stderr || inst.stdout).trim().slice(0, 200)}`);
83	  await exec(conn, "systemctl enable --now postgresql", SETUP_TIMEOUT_MS);
84	}
85	
86	// ---------------------------------------------------------------------------
87	
88	export async function dbCreate(job: Job): Promise<void> {
89	  const row = await loadDb(job);
90	  try {
91	    // Validate again before anything can reach a shell/SQL.
92	    assert(row.engine === "mysql" || row.engine === "postgres", `Unsupported engine: ${row.engine}`);
93	    assertIdent(row.name, "database name");
94	    assertIdent(row.dbUser, "database user");
95	
96	    if (REAL) {
97	      const password = decryptSecret(row.passwordEnc);
98	      assert(password, "Generated password is missing or could not be decrypted.");
99	      const server = await sshServer(row.serverId);
100	      await withServerSsh(server, async (conn) => {
101	        if (row.engine === "mysql") {
102	          await ensureMysql(conn);
103	          // Root socket auth (Debian/Ubuntu default). Password only in the SQL
104	          // body, streamed via STDIN — never an argv token.
105	          const sql =
106	            `CREATE DATABASE IF NOT EXISTS \`${row.name}\` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;\n` +
107	            `CREATE USER IF NOT EXISTS '${row.dbUser}'@'localhost' IDENTIFIED BY '${password}';\n` +
108	            `ALTER USER '${row.dbUser}'@'localhost' IDENTIFIED BY '${password}';\n` +
109	            `GRANT ALL PRIVILEGES ON \`${row.name}\`.* TO '${row.dbUser}'@'localhost';\n` +
110	            `FLUSH PRIVILEGES;\n`;
111	          const r = await execInput(conn, "mysql --protocol=socket -uroot", sql, SETUP_TIMEOUT_MS);
112	          if (r.code !== 0) throw new Error(`MySQL create failed: ${(r.stderr || r.stdout).trim().slice(0, 200)}`);
113	        } else {
114	          await ensurePostgres(conn);
115	          // Run as the postgres superuser. Role password only in the SQL body via STDIN.
116	          const sql =
117	            `CREATE ROLE "${row.dbUser}" LOGIN PASSWORD '${password}';\n` +
118	            `CREATE DATABASE "${row.name}" OWNER "${row.dbUser}";\n` +
119	            `GRANT ALL PRIVILEGES ON DATABASE "${row.name}" TO "${row.dbUser}";\n`;
120	          const r = await execInput(conn, "sudo -u postgres psql -v ON_ERROR_STOP=1", sql, SETUP_TIMEOUT_MS);
121	          if (r.code !== 0) throw new Error(`PostgreSQL create failed: ${(r.stderr || r.stdout).trim().slice(0, 200)}`);
122	        }
123	      });
124	    }
125	    // Scrub the transient secret regardless of path.
126	    await db.vpsDatabase.update({ where: { id: row.id }, data: { status: "ACTIVE", error: null, passwordEnc: null } });
127	    await notify(
128	      row.userId,
129	      `Database "${row.name}" is ready`,
130	      REAL ? `Your ${row.engine} database and user are provisioned.` : `Database created (sandbox — no real VM was touched).`,
131	      `/dashboard/servers/${row.serverId}?tab=control panel`
132	    );
133	  } catch (e: any) {
134	    const reason = String(e?.message ?? e).slice(0, 400);
135	    // Even on failure, do not keep the secret around.
136	    await db.vpsDatabase.update({ where: { id: row.id }, data: { status: "FAILED", error: reason, passwordEnc: null } });
137	    await notify(row.userId, `Database "${row.name}" failed`, reason.slice(0, 200), `/dashboard/servers/${row.serverId}`);
138	  }
139	}
