141	export async function dbDelete(job: Job): Promise<void> {
142	  const row = await loadDb(job);
143	  try {
144	    assert(row.engine === "mysql" || row.engine === "postgres", `Unsupported engine: ${row.engine}`);
145	    assertIdent(row.name, "database name");
146	    assertIdent(row.dbUser, "database user");
147	    if (REAL) {
148	      const server = await sshServer(row.serverId);
149	      await withServerSsh(server, async (conn) => {
150	        if (row.engine === "mysql") {
151	          const sql =
152	            `DROP DATABASE IF EXISTS \`${row.name}\`;\n` +
153	            `DROP USER IF EXISTS '${row.dbUser}'@'localhost';\n` +
154	            `FLUSH PRIVILEGES;\n`;
155	          await execInput(conn, "mysql --protocol=socket -uroot", sql, SETUP_TIMEOUT_MS);
156	        } else {
157	          const sql =
158	            `DROP DATABASE IF EXISTS "${row.name}";\n` +
159	            `DROP ROLE IF EXISTS "${row.dbUser}";\n`;
160	          await execInput(conn, "sudo -u postgres psql", sql, SETUP_TIMEOUT_MS);
161	        }
162	      });
163	    }
164	    await db.vpsDatabase.delete({ where: { id: row.id } });
165	  } catch (e: any) {
166	    await db.vpsDatabase.update({ where: { id: row.id }, data: { status: "FAILED", error: String(e?.message ?? e).slice(0, 400) } });
167	  }
168	}
