205	export async function createWebsite(
206	  serverId: string,
207	  domainInput: string,
208	  phpVersion: string | null,
209	  parentDomain?: string
210	): Promise<CreateResult> {
211	  try {
212	    const { user, server } = await ownedServer(serverId);
213	    const limited = throttle(user.id, "create", 10);
214	    if (limited) return { ok: false, error: limited };
215	    if (server.status !== "RUNNING") return { ok: false, error: "The server must be running to add a website." };
216	    if (await lifecycleBusy(server.id))
217	      return { ok: false, error: "Another server operation is in progress — try again shortly." };
218	
219	    const domain = String(domainInput ?? "").toLowerCase().trim().replace(/\.$/, "");
220	    if (!DOMAIN_RE.test(domain))
221	      return { ok: false, error: "Enter a valid domain (e.g. example.com or blog.example.com)." };
222	
223	    const php = phpVersion ? String(phpVersion).trim() : null;
224	    if (php && (!PHP_VERSION_RE.test(php) || !(PHP_VERSIONS as readonly string[]).includes(php)))
225	      return { ok: false, error: "Choose a supported PHP version." };
226	
227	    const isSubdomain = !!parentDomain;
228	    const parent = parentDomain ? String(parentDomain).toLowerCase().trim() : null;
229	    if (parent && !DOMAIN_RE.test(parent)) return { ok: false, error: "Invalid parent domain." };
230	
231	    const existing = await db.website.findFirst({ where: { serverId: server.id, domain } });
232	    if (existing) return { ok: false, error: `A website for ${domain} already exists on this server.` };
233	
234	    const count = await db.website.count({ where: { serverId: server.id } });
235	    if (count >= 50) return { ok: false, error: "Website limit reached (50 per server)." };
236	
237	    const docRoot = `/var/www/${domain}`;
238	    const site = await db.website.create({
239	      data: {
240	        userId: user.id,
241	        serverId: server.id,
242	        domain,
243	        docRoot,
244	        phpVersion: php,
245	        isSubdomain,
246	        parentDomain: parent,
247	        status: "PENDING",
248	      },
249	    });
250	    await db.job.create({ data: { type: "WEBSITE_CREATE", serverId: server.id, payload: { websiteId: site.id } } });
251	    await db.auditLog.create({
252	      data: { userId: user.id, action: "cpanel.website.create", detail: `${domain} on ${server.hostname}` },
253	    });
254	    revalidatePath(`/dashboard/servers/${serverId}`);
255	    return { ok: true, id: site.id };
256	  } catch (err) {
257	    return { ok: false, error: safeError(err) };
258	  }
259	}
