73	/** Render an nginx server block. All values are allowlist-validated by callers. */
74	export function nginxVhost(domain: string, docRoot: string, phpVersion: string | null): string {
75	  const phpBlock = phpVersion
76	    ? `
77	    location ~ \\.php$ {
78	        include snippets/fastcgi-php.conf;
79	        fastcgi_pass unix:/run/php/php${phpVersion}-fpm.sock;
80	    }
81	`
82	    : "";
83	  return `# Managed by Nxeon control panel — do not edit by hand.
84	server {
85	    listen 80;
86	    listen [::]:80;
87	    server_name ${domain};
88	    root ${docRoot};
89	    index index.php index.html index.htm;
90	
91	    location / {
92	        try_files $uri $uri/ /index.php?$query_string;
93	    }
94	${phpBlock}
95	    access_log /var/log/nginx/${domain}.access.log;
96	    error_log /var/log/nginx/${domain}.error.log;
97	}
98	`;
