101	export async function ensureNginx(conn: import("ssh2").Client): Promise<void> {
102	  const have = await exec(conn, "command -v nginx >/dev/null 2>&1 && echo yes || echo no", QUICK_TIMEOUT_MS);
103	  if (have.stdout.trim() !== "yes") {
104	    const prefix = await pkgInstallPrefix(conn);
105	    const inst = await exec(conn, `${prefix} nginx`, INSTALL_TIMEOUT_MS);
106	    if (inst.code !== 0) throw new Error(`nginx install failed: ${(inst.stderr || inst.stdout).trim().slice(0, 200)}`);
107	  }
108	  // Ensure the sites-available/enabled layout exists (Debian/Ubuntu default).
109	  await exec(conn, "mkdir -p /etc/nginx/sites-available /etc/nginx/sites-enabled", SETUP_TIMEOUT_MS);
110	}
