128	export async function reloadNginx(conn: import("ssh2").Client): Promise<void> {
129	  const test = await exec(conn, "nginx -t", SETUP_TIMEOUT_MS);
130	  if (test.code !== 0) throw new Error(`nginx config test failed: ${(test.stderr || test.stdout).trim().slice(0, 200)}`);
131	  await exec(conn, "systemctl reload nginx || systemctl restart nginx", SETUP_TIMEOUT_MS);
132	}
