200	  const site = await loadSite(job);
201	  try {
202	    if (REAL) {
203	      assertDomain(site.domain);
204	      const server = await sshServer(site.serverId);
205	      const email = process.env.CERTBOT_EMAIL || "ssl-admin@nxeon.local";
206	      await withServerSsh(server, async (conn) => {
207	        const have = await exec(conn, "command -v certbot >/dev/null 2>&1 && echo yes || echo no", QUICK_TIMEOUT_MS);
208	        if (have.stdout.trim() !== "yes") {
209	          const prefix = await pkgInstallPrefix(conn);
