211	          if (inst.code !== 0) throw new Error(`certbot install failed: ${(inst.stderr || inst.stdout).trim().slice(0, 200)}`);
212	        }
213	        // Use the nginx installer so the vhost is upgraded to 443 in place.
214	        const run = await exec(
215	          conn,
216	          `certbot --nginx -n --agree-tos -m ${shellQuote(email)} -d ${shellQuote(site.domain)} --redirect`,
217	          INSTALL_TIMEOUT_MS
218	        );
219	        const combined = `${run.stdout}\n${run.stderr}`;
220	        const ok = run.code === 0 && /Congratulations|Successfully|not yet due for renewal|Deploying certificate/i.test(combined);
221	        if (!ok) throw new Error(`certbot failed: ${combined.trim().slice(0, 300)}`);
222	      });
