229	export async function removeApp(id: string): Promise<Result> {
230	  try {
231	    const { user, app } = await ownedApp(id);
232	    const limited = throttle(user.id, "remove", 10);
233	    if (limited) return { ok: false, error: limited };
234	    if (app.status === "INSTALLING") return { ok: false, error: "This app is still installing — try again shortly." };
235	
236	    // Tear down the provisioned site + database via their own worker jobs, then
237	    // drop the AppInstall record. The site/db rows carry the SSH cleanup.
238	    if (app.websiteId) {
239	      const site = await db.website.findUnique({ where: { id: app.websiteId } });
240	      if (site) {
241	        await db.website.update({ where: { id: site.id }, data: { status: "DELETING", appSlug: null } });
242	        await db.job.create({ data: { type: "WEBSITE_DELETE", serverId: app.serverId, payload: { websiteId: site.id } } });
243	      }
244	    }
245	    if (app.databaseId) {
246	      const database = await db.vpsDatabase.findUnique({ where: { id: app.databaseId } });
247	      if (database) {
248	        await db.vpsDatabase.update({ where: { id: database.id }, data: { status: "DELETING" } });
249	        await db.job.create({ data: { type: "DB_DELETE", serverId: app.serverId, payload: { databaseId: database.id } } });
250	      }
251	    }
252	    await db.appInstall.delete({ where: { id } });
253	    await db.auditLog.create({
254	      data: { userId: user.id, action: "cpanel.app.remove", detail: `${app.appSlug} (${app.domain})` },
255	    });
256	    revalidatePath(`/dashboard/servers/${app.serverId}`);
257	    return { ok: true };
258	  } catch (err) {
259	    return { ok: false, error: safeError(err) };
260	  }
261	}
