80	/** Download + configure WordPress core into docRoot with the provisioned DB. */
81	async function installWordpress(
82	  conn: Client,
83	  docRoot: string,
84	  db_: { name: string; user: string; password: string }
85	) {
86	  assertPath(docRoot);
87	  // Fetch + extract core (curl/tar available on the platform base images).
88	  const dl =
89	    `cd ${shellQuote(docRoot)} && curl -fsSL https://wordpress.org/latest.tar.gz -o /tmp/wp.tgz && ` +
90	    `tar -xzf /tmp/wp.tgz --strip-components=1 -C ${shellQuote(docRoot)} && rm -f /tmp/wp.tgz`;
91	  const r = await exec(conn, dl, INSTALL_TIMEOUT_MS);
92	  if (r.code !== 0) throw new Error(`WordPress download failed: ${(r.stderr || r.stdout).trim().slice(0, 200)}`);
93	  // wp-config.php — DB creds live in the file body written via STDIN, never argv.
94	  const salts = `define('AUTH_KEY', '${rand()}');\n`; // minimal; WP still works without unique salts
95	  const cfg =
96	    `<?php\n` +
97	    `define('DB_NAME', '${db_.name}');\n` +
98	    `define('DB_USER', '${db_.user}');\n` +
99	    `define('DB_PASSWORD', '${db_.password}');\n` +
100	    `define('DB_HOST', 'localhost');\n` +
101	    `define('DB_CHARSET', 'utf8mb4');\n` +
102	    `define('DB_COLLATE', '');\n` +
103	    `$table_prefix = 'wp_';\n` +
104	    salts +
105	    `define('WP_DEBUG', false);\n` +
106	    `if ( ! defined('ABSPATH') ) define('ABSPATH', __DIR__ . '/');\n` +
107	    `require_once ABSPATH . 'wp-settings.php';\n`;
108	  await execInput(conn, `cat > ${shellQuote(docRoot + "/wp-config.php")}`, cfg, SETUP_TIMEOUT_MS);
109	  await exec(conn, `chown -R www-data:www-data ${shellQuote(docRoot)} 2>/dev/null || true`, SETUP_TIMEOUT_MS);
110	}
