229	/** Lightweight stat used to disambiguate file vs. dir before an action. */
230	export async function statEntry(
231	  serverId: string,
232	  path: string
233	): Promise<{ ok: true; isDirectory: boolean; size: number } | { ok: false; error: string }> {
234	  try {
235	    const { user, server } = await ownedServer(serverId);
236	    const limited = throttle(user.id, "stat", 120);
237	    if (limited) return { ok: false, error: limited };
238	    const clean = normalizePath(path);
239	    const s = await statPath(server, clean);
240	    return { ok: true, isDirectory: s.isDirectory, size: s.size };
241	  } catch (err) {
242	    return { ok: false, error: safeError(err) };
243	  }
244	}
