386	export async function renamePath(
387	  server: SftpServer,
388	  from: string,
389	  to: string
390	): Promise<void> {
391	  if (SANDBOX) {
392	    const src = simResolve(server.id, from);
393	    if (!src) throw new Error("No such file or directory.");
394	    const dst = simParent(server.id, to);
395	    if (!dst) throw new Error("Invalid destination.");
396	    if (dst.parent.children[dst.name]) {
397	      throw new Error("A file or folder with that name already exists.");
398	    }
399	    const srcLoc = simParent(server.id, from);
400	    if (!srcLoc) throw new Error("Cannot rename the root.");
401	    delete srcLoc.parent.children[srcLoc.name];
402	    dst.parent.children[dst.name] = { ...src, mtime: Date.now() };
403	    return;
404	  }
405	
406	  await withSftp(server, async (client) => {
407	    await client.rename(from, to);
408	  });
409	}
