14	/**
15	 * File download / upload endpoint for the in-portal file manager.
16	 *
17	 *   GET  /api/files/[serverId]?path=/abs/file&download=1   -> streams the file
18	 *   POST /api/files/[serverId]?path=/abs/dir               -> multipart upload
19	 *
20	 * Both are authenticated and ownership-checked (owner or admin), path-validated
21	 * (absolute, no `..`), size-capped, and rate-limited. Real SFTP in production;
22	 * an in-memory simulation on the sandbox (handled inside lib/sftp).
23	 */
24	export const dynamic = "force-dynamic";
25	
26	/** Max upload size accepted per request. */
27	const MAX_UPLOAD_BYTES = 100 * 1024 * 1024; // 100 MB
28	
29	async function ownedServer(
30	  serverId: string,
31	  userId: string,
32	  isAdmin: boolean
33	): Promise<SftpServer | null> {
34	  const server = await db.server.findUnique({
35	    where: { id: serverId },
36	    select: {
37	      id: true,
38	      userId: true,
39	      rootPassword: true,
40	      sshPort: true,
41	      dedicatedIp: { select: { address: true } },
42	    },
43	  });
44	  if (!server) return null;
45	  if (server.userId !== userId && !isAdmin) return null;
46	  return server;
47	}
