168	    }
169	    const note = comment ? String(comment).replace(/[\x00-\x1f\x7f]/g, "").trim().slice(0, 80) : null;
170	
171	    const count = await db.cronJob.count({ where: { serverId: server.id } });
172	    if (count >= 50) return { ok: false, error: "Cron job limit reached (50 per server)." };
