46	async function sshServer(serverId: string): Promise<SftpServer> {
47	  const s = await db.server.findUnique({
48	    where: { id: serverId },
49	    select: {
50	      id: true,
51	      rootPassword: true,
52	      rootPasswordEnc: true,
53	      sshPort: true,
54	      dedicatedIp: { select: { address: true } },
55	    },
56	  });
57	  if (!s) throw new Error(`Server ${serverId} not found`);
58	  return s as SftpServer;
59	}
