61	/** Strip any existing Nxeon-managed block from an existing crontab body. */
62	function stripManaged(current: string): string {
63	  const lines = current.split("\n");
64	  const out: string[] = [];
65	  let inBlock = false;
66	  for (const line of lines) {
67	    if (line.trim() === BEGIN) {
68	      inBlock = true;
69	      continue;
70	    }
71	    if (line.trim() === END) {
72	      inBlock = false;
73	      continue;
74	    }
75	    if (!inBlock) out.push(line);
76	  }
77	  return out.join("\n").replace(/\n{3,}/g, "\n\n").trimEnd();
78	}
79	
80	export async function cronSync(job: Job): Promise<void> {
81	  if (!job.serverId) throw new Error("cron sync: missing serverId");
82	  const serverId = job.serverId;
83	
84	  // Remove any DELETING rows first — they must not reappear in the crontab.
85	  await db.cronJob.deleteMany({ where: { serverId, status: "DELETING" } });
86	
87	  const rows = await db.cronJob.findMany({ where: { serverId }, orderBy: { createdAt: "asc" } });
88	  const enabled = rows.filter((r) => r.enabled);
89	
90	  // Build the managed block (validate every schedule again).
91	  const blockLines = [BEGIN];
92	  for (const r of enabled) {
93	    const sched = assertCronSchedule(r.schedule); // throws on anything unexpected
94	    if (r.comment) blockLines.push(`# ${r.comment.replace(/[\r\n]/g, " ").slice(0, 80)}`);
95	    // command validated at enqueue time (no newline/control chars).
96	    blockLines.push(`${sched} ${r.command}`);
97	  }
98	  blockLines.push(END);
99	  const managedBlock = blockLines.join("\n");
100	
101	  try {
102	    if (REAL) {
103	      const server = await sshServer(serverId);
104	      await withServerSsh(server, async (conn) => {
105	        const cur = await exec(conn, "crontab -l 2>/dev/null || true", QUICK_TIMEOUT_MS);
106	        const base = stripManaged(cur.stdout);
107	        const body = (base ? base + "\n\n" : "") + managedBlock + "\n";
108	        // Install the whole crontab via STDIN — user command lines are data here,
109	        // never a shell we execute.
110	        const r = await execInput(conn, "crontab -", body, SETUP_TIMEOUT_MS);
111	        if (r.code !== 0) throw new Error(`crontab install failed: ${(r.stderr || r.stdout).trim().slice(0, 200)}`);
112	      });
113	    }
114	    await db.cronJob.updateMany({ where: { serverId }, data: { status: "ACTIVE", error: null } });
115	  } catch (e: any) {
116	    const reason = String(e?.message ?? e).slice(0, 400);
117	    await db.cronJob.updateMany({ where: { serverId, status: "PENDING" }, data: { status: "FAILED", error: reason } });
118	    const first = rows[0];
119	    if (first) await notify(first.userId, "Cron update failed", reason.slice(0, 200), `/dashboard/servers/${serverId}`);
120	  }
121	}
