321	 *
322	 * The DKIM record is fetched from Mailcow (`mcGetDkim`) and cached in
323	 * `dkimRecord`; when Mailcow isn't configured (or has no key yet) a placeholder
324	 * note is returned so the panel still renders.
325	 */
326	export async function getEmailDnsRecords(
327	  subscriptionId: string,
328	): Promise<{
329	  error?: string;
330	  records?: DnsRecord[];
331	  verified?: boolean;
332	  external?: boolean;
333	  cloudflareConnected?: boolean;
334	}> {
335	  const user = await requireUser();
336	
337	  const sub = await db.emailSubscription.findUnique({ where: { id: subscriptionId } });
338	  if (!sub) return { error: "Subscription not found." };
339	  if (sub.userId !== user.id) return { error: "Not your subscription." };
340	
341	  const domain = sub.domainName;
342	
343	  // Resolve the DKIM TXT: prefer the cached value, else fetch + cache from Mailcow.
344	  let dkimTxt = sub.dkimRecord ?? null;
345	  if (!dkimTxt && mailcowConfigured()) {
346	    try {
347	      // Ensure the mail domain exists so Mailcow has generated a DKIM key.
348	      if (!(await mcDomainExists(domain))) {
349	        await mcCreateDomain(domain).catch(() => {});
350	      }
351	      dkimTxt = await mcGetDkim(domain);
352	      if (dkimTxt) {
353	        await db.emailSubscription
354	          .update({ where: { id: sub.id }, data: { dkimRecord: dkimTxt } })
355	          .catch(() => {});
356	      }
357	    } catch (e) {
358	      console.warn(`[mailcow] get dkim ${domain} failed:`, e);
359	    }
360	  }
361	
362	  const records: DnsRecord[] = [
363	    {
364	      type: "TXT",
365	      label: "Ownership verification",
366	      host: `_nxeon-verify.${domain}`,
367	      value: `nxeon-verify=${sub.verifyToken ?? ""}`,
368	      note: "Proves you control this domain. Required before mail is enabled.",
369	    },
370	    {
371	      type: "MX",
372	      label: "Mail routing (MX)",
373	      host: domain,
374	      value: MAIL_HOST,
375	      priority: MAIL_MX_PRIORITY,
376	    },
377	    {
378	      type: "TXT",
