491	export async function addMailbox(subscriptionId: string, localPart: string): Promise<Result> {
492	  const user = await requireUser();
493	
494	  const sub = await db.emailSubscription.findUnique({
495	    where: { id: subscriptionId },
496	    include: { emailPlan: true, mailboxes: true },
497	  });
498	  if (!sub) return { error: "Subscription not found." };
499	  if (sub.userId !== user.id) return { error: "Not your subscription." };
500	  if (sub.status === "CANCELLED") return { error: "This subscription is cancelled." };
501	
502	  const local = String(localPart ?? "").trim().toLowerCase();
503	  if (!localPartRe.test(local) || local.length > 64) {
504	    return { error: "Enter a valid mailbox name (letters, numbers, . _ - )." };
505	  }
506	
507	  const address = `${local}@${sub.domainName}`;
508	
509	  if (sub.mailboxes.length >= sub.emailPlan.mailboxes) {
510	    return {
511	      error: `Plan limit reached (${sub.emailPlan.mailboxes} mailbox${sub.emailPlan.mailboxes === 1 ? "" : "es"}). Upgrade to add more.`,
512	    };
513	  }
514	  if (sub.mailboxes.some((m) => m.address.toLowerCase() === address)) {
515	    return { error: "That address already exists." };
516	  }
517	
518	  // Per-mailbox quota (MB) comes from the plan tier's per-mailbox storage (GB).
519	  const quotaMB = sub.emailPlan.storageGB * 1024;
520	
521	  const mailbox = await db.mailbox.create({
522	    data: { subscriptionId: sub.id, address, quotaMB, status: "PROVISIONING" },
523	  });
