768	/**
769	 * Auto-create the mail DNS records for an EXTERNAL email subscription in the
770	 * customer's Cloudflare zone, using their stored token. Ownership-checked and
771	 * rate-limited. Reuses getEmailDnsRecords as the single source of truth for the
772	 * record set (ownership verify TXT, MX, SPF, DKIM, DMARC), upserts each into the
773	 * zone, then leaves the existing verifyEmailDomain flow to confirm. Fails
774	 * gracefully with clear messages for invalid token / zone-not-found.
775	 */
776	export async function autoCreateEmailDns(
777	  subscriptionId: string,
778	): Promise<{ error?: string; ok?: boolean; created?: string[] }> {
779	  const user = await requireUser();
780	
781	  const sub = await db.emailSubscription.findUnique({ where: { id: subscriptionId } });
782	  if (!sub) return { error: "Subscription not found." };
783	  if (sub.userId !== user.id) return { error: "Not your subscription." };
784	  if (!sub.external) {
785	    return { error: "This domain is managed by Nxeon — no external DNS setup is needed." };
786	  }
787	
788	  const rl = checkRateLimit(`cf-autodns:${user.id}:${sub.id}`, { max: 4, windowMs: 60_000 });
789	  if (!rl.ok) return { error: `Too many attempts. Try again in ${rl.retryAfterSec}s.` };
790	
791	  // Works for both connection shapes: OAuth credentials (refreshed here when
792	  // stale) and a legacy pasted API token. Never handles the plaintext itself.
793	  const resolved = await resolveCloudflareToken(user);
794	  const token = resolved.token;
795	  if (!token) return { error: resolved.error ?? "Connect Cloudflare first." };
796	
797	  // Same record set the customer would otherwise publish by hand.
798	  const dns = await getEmailDnsRecords(subscriptionId);
799	  if (dns.error) return { error: dns.error };
800	  const records = (dns.records ?? []).filter((r) => r.type === "MX" || r.value.trim());
801	  if (records.length === 0) {
802	    return { error: "No DNS records to create yet — try again in a moment." };
803	  }
804	
805	  // SANDBOX: never contact Cloudflare — report what we would have published so
806	  // staging can walk the whole "connect → records added" flow.
807	  if (SANDBOX) {
808	    return {
809	      ok: true,
810	      created: records.map((r) => `${r.label} (${r.type}, created)`),
811	    };
812	  }
813	
814	  let zoneId: string | null;
815	  try {
816	    zoneId = await cfFindZoneId(token, sub.domainName);
817	  } catch (e) {
818	    if (e instanceof CloudflareError) {
819	      return { error: `Cloudflare error: ${e.message}` };
820	    }
821	    throw e;
822	  }
823	  if (!zoneId) {
824	    return {
825	      error: `No Cloudflare zone found for ${sub.domainName}. Add the domain to Cloudflare first, or check the token is scoped to this zone.`,
826	    };
827	  }
828	
829	  let created: string[];
830	  try {
831	    const results = await cfUpsertRecords(
832	      token,
833	      zoneId,
834	      records.map((r) => ({
835	        type: r.type,
836	        name: r.host,
837	        content: r.value,
838	        priority: r.priority,
839	      })),
840	    );
841	    created = results.map((res) => {
842	      const label = records.find((r) => r.host === res.name && r.type === res.type)?.label ?? res.name;
843	      return `${label} (${res.type}, ${res.action})`;
844	    });
845	  } catch (e) {
846	    if (e instanceof CloudflareError) {
847	      return {
848	        error: `Couldn't create records in Cloudflare: ${e.message}. Check the token has Zone → DNS → Edit permission.`,
849	      };
850	    }
851	    throw e;
852	  }
853	
854	  await db.auditLog.create({
855	    data: {
856	      userId: user.id,
857	      action: "cloudflare.autodns",
858	      detail: `${sub.domainName} — ${created.length} record(s)`,
859	    },
860	  });
861	  revalidatePath("/dashboard/email");
862	  return { ok: true, created };
863	}
