    14	import type { SftpServer } from "./sftp";
    15	
    16	/** Deterministic pseudo-random in [0,1) from a string seed (sandbox realism). */
    17	function seeded(seed: string): number {
    18	  let h = 2166136261;
    19	  for (let i = 0; i < seed.length; i++) {
    20	    h ^= seed.charCodeAt(i);
    21	    h = Math.imul(h, 16777619);
    22	  }
    23	  return ((h >>> 0) % 10000) / 10000;
    24	}
