    26	// ---------------------------------------------------------------------------
    27	// Service status
    28	// ---------------------------------------------------------------------------
    29	
    30	/**
    31	 * Status of the common services. In sandbox, nginx/ssh look running, php-fpm/
    32	 * mysql installed-and-running, the rest a deterministic mix. On prod we ask
    33	 * systemd for each unit in one round-trip.
    34	 */
    35	export async function readServiceStatuses(server: SftpServer): Promise<ServiceStatus[]> {
    36	  if (SANDBOX) {
    37	    return COMMON_SERVICES.map((s) => {
    38	      let state: ServiceStatus["state"];
    39	      if (s.unit === "nginx" || s.unit === "ssh") state = "running";
    40	      else if (s.unit === "php-fpm" || s.unit === "mysql") state = "running";
    41	      else state = seeded(server.id + s.unit) > 0.5 ? "running" : "not-installed";
    42	      return { unit: s.unit, label: s.label, state };
    43	    });
    44	  }
    45	
    46	  return withServerSsh(server, async (conn) => {
    47	    const out: ServiceStatus[] = [];
    48	    for (const s of COMMON_SERVICES) {
    49	      assertService(s.unit);
    50	      const q = shellQuote(s.unit);
    51	      // is-active prints active/inactive/failed/unknown; if the unit doesn't
    52	      // exist at all, `systemctl list-unit-files` finds nothing → not-installed.
    53	      const r = await exec(
    54	        conn,
    55	        `if systemctl list-unit-files ${q}.service >/dev/null 2>&1 || systemctl status ${q} >/dev/null 2>&1; then ` +
    56	          `systemctl is-active ${q} 2>/dev/null || echo inactive; else echo missing; fi`,
    57	        QUICK_TIMEOUT_MS
    58	      );
    59	      const v = r.stdout.trim();
    60	      let state: ServiceStatus["state"];
    61	      if (v === "active") state = "running";
    62	      else if (v === "missing") state = "not-installed";
    63	      else if (v === "inactive" || v === "failed") state = "stopped";
    64	      else state = "unknown";
    65	      out.push({ unit: s.unit, label: s.label, state });
    66	    }
    67	    return out;
    68	  });
    69	}
